{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.sql.*;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;
import org.json.JSONArray;
import org.json.JSONObject;
import org.joget.plugin.base.PluginManager;
import org.joget.workflow.model.service.WorkflowManager;

final String LOGGER = "IOC-BeanShell";
final String REQ_TBL = "app_fd_eth_ioc_item_request";
final String HV_REQ_ID = "#form.eth_ioc_item_request.id#";


String hv(String expr){
 try{
 String v = AppUtil.processHashVariable(expr, workflowAssignment, null, null);
 if (v == null) return null;
 v = v.trim();
 return (v.length()==0 || v.indexOf('#')>=0) ? null : v;
 }catch(Exception e){ return null; }
}
boolean blank(String s){ return s==null || s.trim().isEmpty() || "null".equalsIgnoreCase(s.trim()); }

/* ===== MAIN ===== */
Connection con=null; PreparedStatement ps=null; ResultSet rs=null;
try{
 String reqId = hv(HV_REQ_ID);
 if (reqId == null){
 LogUtil.warn(LOGGER, "Request ID not resolved.");
 // still clear the variable so UI doesn't show stale data
 PluginManager pm = (PluginManager) AppUtil.getApplicationContext().getBean("pluginManager");
 WorkflowManager wm = (WorkflowManager) pm.getBean("workflowManager");
 wm.activityVariable(workflowAssignment.getActivityId(), "merge_inputs_title", "");
 return "no-id";
 }

 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();

 ps = con.prepareStatement("SELECT c_addRawMaterialItem FROM " + REQ_TBL + " WHERE id=?");
 ps.setString(1, reqId);
 rs = ps.executeQuery();

 String itemsJson = null;
 if (rs.next()){
 itemsJson = rs.getString("c_addRawMaterialItem");
 } else {
 LogUtil.warn(LOGGER, "No request row found for id=" + reqId);
 }

 String mergedTitles = "";
 if (!blank(itemsJson)){
 try{
 JSONArray arr = new JSONArray(itemsJson);
 StringBuilder sb = new StringBuilder();
 for (int i=0; i<arr.length(); i++){
 JSONObject obj = arr.optJSONObject(i);
 if (obj == null) continue;
 String title = obj.optString("input_description", null);


 if (!blank(title)){
 if (sb.length() > 0) sb.append(", ");
 sb.append(title);
 }
 }
 mergedTitles = sb.toString();
 }catch(Exception je){
 LogUtil.warn(LOGGER, "Invalid JSON in c_addRawMaterialItem for id=" + reqId + ": " + je.getMessage());
 }
 } else {
 LogUtil.info(LOGGER, "Empty or null c_addRawMaterialItem for id=" + reqId);
 }

 try{
 PluginManager pm = (PluginManager) AppUtil.getApplicationContext().getBean("pluginManager");
 WorkflowManager wm = (WorkflowManager) pm.getBean("workflowManager");
 wm.activityVariable(workflowAssignment.getActivityId(), "merge_inputs_title", mergedTitles);
 LogUtil.info(LOGGER, "Set merge_inputs_title = " + mergedTitles);
 }catch(Exception wex){
 LogUtil.warn(LOGGER, "Failed to set workflow variable 'merge_inputs_title': " + wex.getMessage());
 }

 return "success";

}catch(Exception e){
 LogUtil.error(LOGGER, e, "FAILED: " + e.getMessage());
 try{
 PluginManager pm = (PluginManager) AppUtil.getApplicationContext().getBean("pluginManager");
 WorkflowManager wm = (WorkflowManager) pm.getBean("workflowManager");
 wm.activityVariable(workflowAssignment.getActivityId(), "merge_inputs_title", "");
 }catch(Exception ignore){}
 return "error";
}finally{
 try{ if(rs!=null) rs.close(); }catch(Exception ig){}
 try{ if(ps!=null) ps.close(); }catch(Exception ig){}
 try{ if(con!=null) con.close(); }catch(Exception ig){}
}
"}}]}

