final String LOGGER = "SIOC-Import";
final String FORM_TABLE = "app_fd_eth_ioc_import";
final String FORM_FOLDER = "eth_ioc_import";
final String FORM_DATA_ID_FIELD = "#form.app_fd_eth_ioc_import.id#"; 
final String PRODUCT_TABLE = "app_fd_eth_ioc_products";
final String TYPE_TABLE = "app_fd_eth_ioc_raw_mat_type";
final String ITEM_TABLE = "app_fd_eth_ioc_raw_mat_item";

Connection dbConnection = null;

// =================== HELPERS ===================
String fetchProcessHashedVariable(String hashedVariableName) {
 try {
 String hashedVariableValue = AppUtil.processHashVariable(hashedVariableName, workflowAssignment, null, null);
 if (hashedVariableValue == null) {
 return null;
 }
 hashedVariableValue = hashedVariableValue.trim();
 return (hashedVariableValue.isEmpty() || hashedVariableValue.indexOf('#') >= 0) ? null :hashedVariableValue;
 } catch (Exception e) { return null; }
}

String fetchFilePath(String fileName, String formDataId) {
 SetupManager setupManager = (SetupManager) AppUtil.getApplicationContext().getBean("setupManager");
 String formUploadPath = setupManager.getBaseDirectory();
 String dataFileBasePath = setupManager.getSettingValue("dataFileBasePath");
 if (dataFileBasePath != null && dataFileBasePath.length() > 0) {
 formUploadPath = dataFileBasePath;
 }
 String filePath = formUploadPath + File.separator + "app_formuploads" + File.separator + FORM_FOLDER + File.separator + formDataId + File.separator + fileName;
 return filePath;
}

void setNullableString(PreparedStatement ps, int i, String v) throws SQLException {
 if (v == null) ps.setNull(i, Types.VARCHAR); else ps.setString(i, v);
}

String getProductIdByCode(String productCode) {
 PreparedStatement ps = null;
 ResultSet rs = null;
 String productId = null;
 try {
 ps = dbConnection.prepareStatement("SELECT id FROM " + PRODUCT_TABLE + " WHERE c_product_code = ?");
 ps.setString(1, productCode);
 rs = ps.executeQuery();
 if (rs.next()) {
 productId = rs.getString("id");
 }
 } catch (Exception e) {
 LogUtil.error(LOGGER, e, "Error fetching Product by code: " + e.getMessage());
 } finally {
 try { if (rs != null) rs.close(); } catch (Exception ex) {}
 try { if (ps != null) ps.close(); } catch (Exception ex) {}
 }
 return productId; 
}

String getTypeIdByCodeAndProduct(String typeCode, String productId) {
 PreparedStatement ps = null;
 ResultSet rs = null;
 String typeId = null;
 try {
 ps = dbConnection.prepareStatement("SELECT id FROM " + TYPE_TABLE + " WHERE c_raw_material_type_code = ? AND c_product = ?");
 ps.setString(1, typeCode);
 ps.setString(2, productId);
 rs = ps.executeQuery();
 if (rs.next()) {
 typeId = rs.getString("id");
 }
 } catch (Exception e) {
 LogUtil.error(LOGGER, e, "Error fetching Type by code: " + e.getMessage());
 } finally {
 try { if (rs != null) rs.close(); } catch (Exception ex) {}
 try { if (ps != null) ps.close(); } catch (Exception ex) {}
 }
 return typeId; 
}

String getItemIdByCodeAndType(String itemCode, String typeId) {
 PreparedStatement ps = null;
 ResultSet rs = null;
 String itemId = null;
 try {
 ps = dbConnection.prepareStatement("SELECT id FROM " + ITEM_TABLE + " WHERE c_input_code = ? AND c_raw_material_type = ?");
 ps.setString(1, itemCode);
 ps.setString(2, typeId);
 rs = ps.executeQuery();
 if (rs.next()) {
 itemId = rs.getString("id");
 }
 } catch (Exception e) {
 LogUtil.error(LOGGER, e, "Error fetching Item by code: " + e.getMessage());
 } finally {
 try { if (rs != null) rs.close(); } catch (Exception ex) {}
 try { if (ps != null) ps.close(); } catch (Exception ex) {}
 }
 return itemId; 
}

try {
 String formDataId = fetchProcessHashedVariable(FORM_DATA_ID_FIELD);
 String processId = workflowAssignment.getProcessId(); 

 if (formDataId == null) { 
 LogUtil.warn(LOGGER, "Form data ID not resolved"); return "no-id"; 
 }

 String userEmail = fetchProcessHashedVariable("#currentUser.email#");
 String userFirstName = fetchProcessHashedVariable("#currentUser.firstName#");
