 if (dataSource == null) { LogUtil.warn(LOGGER, "DataSource 'setupDataSource' not found."); return "no-datasource"; }
 dbConnection = dataSource.getConnection();
 if (dbConnection == null) { LogUtil.warn(LOGGER, "No DB connection."); return "no-connection"; }
 dbConnection.setAutoCommit(true);

 PreparedStatement formDataPreparedStatement = dbConnection.prepareStatement(
 "SELECT c_uploadCSV FROM " + FORM_TABLE + " WHERE id = ?"
 );
 formDataPreparedStatement.setString(1, formDataId);
 ResultSet formDataResultSet = formDataPreparedStatement.executeQuery();
 if (!formDataResultSet.next()) { 
 LogUtil.warn(LOGGER, "No source row for id=" + formDataId); return "not-found"; 
 }
 String csvFileName = formDataResultSet.getString("c_uploadCSV");
 String filePath = fetchFilePath(csvFileName, formDataId);
 formDataPreparedStatement.close();
 formDataResultSet.close();

 LogUtil.info(LOGGER, "Importing SIOC file with the path: " + filePath);

