 insertProductStatement.setTimestamp(i++, currentTime); // dateCreated
 insertProductStatement.setTimestamp(i++, currentTime); // dateModified
 setNullableString(insertProductStatement, i++, userEmail); // createdBy
 setNullableString(insertProductStatement, i++, userFullName); // createdByName
 setNullableString(insertProductStatement, i++, userEmail); // modifiedBy
 setNullableString(insertProductStatement, i++, userFullName); // modifiedByName
 //update
 setNullableString(insertProductStatement, i++, sectorId); // c_sector (id)
 setNullableString(insertProductStatement, i++, sectorCode); // c_sector_code (from join)
 setNullableString(insertProductStatement, i++, productHSCode); // c_hscode
 setNullableString(insertProductStatement, i++, productTitle); // c_title
 setNullableString(insertProductStatement, i++, productUom); // c_uom
