public String fetchSectorCode(String sectorId) {
 DataSource dataSource = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 if (dataSource == null) { LogUtil.warn(LOGGER, "DataSource 'setupDataSource' not found."); return "no-datasource"; }
 Connection dbConnection = dataSource.getConnection();
 if (dbConnection == null) { LogUtil.warn(LOGGER, "No DB connection."); return "no-connection"; }
 dbConnection.setAutoCommit(true);

 PreparedStatement ps = null;
 ResultSet rs = null;
 String sectorCode = null;
 try {
 ps = dbConnection.prepareStatement("SELECT c_code FROM app_fd_eth_ioc_sector WHERE id = ?");
 ps.setString(1, sectorId);
 rs = ps.executeQuery();
 if (rs.next()) {
 sectorCode = rs.getString("c_code");
 }
 } catch (Exception e) {
 LogUtil.error(LOGGER, e, "Error fetching sector code: " + e.getMessage());
 } finally {
 try { if (rs != null) rs.close(); } catch (Exception ex) {}
 try { if (ps != null) ps.close(); } catch (Exception ex) {}
 }
 return sectorCode; 
}

