public Collection getAssignees(WorkflowActivity activity) {
 Collection assignees = new ArrayList();

 ExtDirectoryManager directoryManager = (ExtDirectoryManager) pluginManager.getBean("directoryManager");
 WorkflowManager wm = (WorkflowManager) WorkflowUtil.getApplicationContext().getBean("workflowManager");

 // -------------------------
 // Get variables from workflowActivity
 // -------------------------
 Collection variableList = wm.getActivityVariableList(activity.getId());
 String sectorId = null;
 String productId = null;
 java.util.Iterator variableIterator = variableList.iterator();
 while(variableIterator.hasNext()) {
 Object obj = variableIterator.next();
 WorkflowVariable var = (WorkflowVariable) obj;
 LogUtil.info("", "process vars: " + var.getName() + " = " + var.getVal());
 if ("productId".equals(var.getName())) {
 productId = (String) var.getVal();
 break;
 }
 }
 LogUtil.info("", "Workflow variable productId: " + productId);
 String sectorId = fetchProductSector(productId);
 String sectorCode = fetchSectorCode(sectorId);
 LogUtil.info("", "Fetched sectorCode: " + sectorCode);

 // -------------------------
 // Read environment variables
 // -------------------------
 String json = "#envVariable.SECTOR_TO_DEPARTMENT_MAPPING?json#";
 String defaultDepartment = "#envVariable.SECTOR_DEFAULT_DEPARTMENT#";
 String defaultGroup = "#envVariable.SECTOR_DEFAULT_GROUP#";
 LogUtil.info("", "SECTOR_TO_DEPARTMENT_MAPPING: " + json + ", SECTOR_DEFAULT_DEPARTMENT: " + defaultDepartment + ", SECTOR_DEFAULT_GROUP: " + defaultGroup);

 // -------------------------
 // Parse JSON mapping
 // -------------------------

 JSONObject mapping = new JSONObject();

 if (json != null && !json.isEmpty()) {
 try {
 mapping = new JSONObject(json);
 } catch (Exception e) {
 LogUtil.error("", "Failed to parse SECTOR_TO_DEPARTMENT_MAPPING JSON: " + e.getMessage(), e);
 }
 }

 // -------------------------
 // Determine candidate department
 // -------------------------
 String candidateDepartmentId = mapping.optString(sectorCode, null);

 LogUtil.info("", "Target Department '" + candidateDepartmentId + "'.");

 DirectoryManager dm = (DirectoryManager) AppUtil.getApplicationContext().getBean("directoryManager");
 String sectorDepartmentId = null;
 Department sectorDepartmentObject = null;

 // -------------------------
 // Check if candidate department exists
 // -------------------------
 if (candidateDepartmentId != null) {
 sectorDepartmentObject = dm.getDepartmentById(candidateDepartmentId);
 }

 // -------------------------
 // Check default department if candidate not found
 // -------------------------
 if (sectorDepartmentObject == null && defaultDepartment != null && defaultDepartment.length() > 0) {
 sectorDepartmentObject = dm.getDepartmentById(defaultDepartment);
 }

 String finalDepartmentOrGroup = null;
 Employment departmentHod = null;
 if (sectorDepartmentObject != null) {
 departmentHod = sectorDepartmentObject.getHod();
 finalDepartmentOrGroup = sectorDepartmentObject.getId();
 }

 // -------------------------
 // Fallback to default group if no department found
 // -------------------------
 if (finalDepartmentOrGroup == null && defaultGroup != null && defaultGroup.length() > 0) {
 finalDepartmentOrGroup = defaultGroup;
 LogUtil.info("", "Falling back to group '" + defaultGroup + "'.");
 }

 // -------------------------
 // Get all users from finalDepartmentOrGroup
 // -------------------------
 if (finalDepartmentOrGroup != null) {
 Long total = directoryManager.getTotalUsers(null, null, finalDepartmentOrGroup, null, null, null, null);
 if (total > 0) {
 Collection userList = directoryManager.getUsers(null, null, finalDepartmentOrGroup, null, null, null, null, "firstName", false, 0, total.intValue());
 java.util.Iterator userIt = userList.iterator();
 while(userIt.hasNext()) {
 Object u = userIt.next();
 User user = (User) u;
 assignees.add(user.getUsername());
 }
 } else {
 LogUtil.info("", "No users found in Department/Group: " + finalDepartmentOrGroup);
 }
 }

 return assignees;
}


// call method with injected workflowActivity
return getAssignees(workflowActivity);"}

